    {
      "name": "_name_parts",
      "signature": "_name_parts(name) -> set[str]",
      "pre_condition": "name is a non-empty string.",
      "post_condition": "Returns a set of lowercase strings, each being a constituent part of the name obtained by splitting at word boundaries such as underscores and case transitions. The union of all parts reconstructs the original name in lowercase when rejoined with their original separators. Each part is a minimal word-like token with no internal delimiters."
    },
    {
      "name": "_fuzzy_name_score",
      "signature": "_fuzzy_name_score(parts, signals) -> float",
      "pre_condition": "parts is a non-empty set of lowercase strings. signals is a dict containing identifier-like signal token sets (including 'plain_idents').",
      "post_condition": "Returns a non-negative float representing the sum of typo-tolerant fuzzy match scores between members of parts and identifier-like signal tokens. A non-zero contribution requires: the part string length and the signal token length both meet a minimum character-length threshold, and their string similarity ratio exceeds a fixed threshold. The total contribution is bounded so that it never exceeds a small fraction of the maximum possible identifier-category score."
    }
  ]
}
"}

{"filePath": "/home/fancy/Projects_Vault/FM-Agent/fm_agent/extracted_functions/src/scope-py/_build_func_list_text.py.spec.json", "content": "{
  "signature": "_build_func_list_text(funcs_info, source_lines) -> str",
  "pre_condition": "funcs_info is a non-empty list of dicts. Each dict contains at minimum a 'name' key with a string value. source_lines is a list of strings.",
  "post_condition": "Returns a string formed by concatenating one formatted line per entry in funcs_info, separated by newline characters. For each function entry, the line contains the function's name and the source text obtained from source_lines at the 0-based index corresponding to the entry's 'start' key (a 1-based line number) with leading and trailing whitespace removed. If the entry has a non-empty 'docstring' key, the first line of the docstring value is appended, truncated to a maximum length of 120 characters; otherwise nothing additional is appended for that entry. Entries are processed in the order they appear in funcs_info. When funcs_info is empty, the result is an empty string. The result depends only on the contents of funcs_info and source_lines."
}
"}

